create table FM_LOC_HOLIDAY (HOLIDAY_TYPE VARCHAR(1) null  ,HOLIDAY_DESC VARCHAR(50) null  ,COUNTRY VARCHAR(3) not null  ,STATE VARCHAR(6) not null  ,HOLIDAY_DATE TIMESTAMP(3) not null  ,WORKING_HOLIDAY VARCHAR(1) null  ,APPLY_IND VARCHAR(1) null  ,COMPANY VARCHAR(20) null  ,TRAN_TIMESTAMP VARCHAR(26) null  , primary key(COUNTRY,STATE,HOLIDAY_DATE));